#!/usr/bin/env bash
# Adjusts the iOS project generated by `npx cap add ios` (runs on the macOS CI runner).
# Usage: patch-ios.sh <marketing version> <build number>   (from the mobile/ folder)
set -euo pipefail

VERSION="$1"
BUILD="$2"
APP="ios/App/App"
PLIST="$APP/Info.plist"
PBX="ios/App/App.xcodeproj/project.pbxproj"
pb() { /usr/libexec/PlistBuddy -c "$1" "$PLIST"; }

# Name shown under the icon
pb "Set :CFBundleDisplayName NianPlay"

# Keep playing with the screen locked / app in the background
pb "Add :UIBackgroundModes array"
pb "Add :UIBackgroundModes:0 string audio"

# The app's Documents folder appears in Files ("No meu iPhone › NianPlay") and in
# Apple Devices/iTunes on the PC — that's where the user drops music (media.js: scanDocuments)
pb "Add :UIFileSharingEnabled bool true"
pb "Add :LSSupportsOpeningDocumentsInPlace bool true"

# Portrait only, like Spotify
pb "Delete :UISupportedInterfaceOrientations"
pb "Add :UISupportedInterfaceOrientations array"
pb "Add :UISupportedInterfaceOrientations:0 string UIInterfaceOrientationPortrait"

pb "Add :ITSAppUsesNonExemptEncryption bool false"

# Version
sed -i '' "s/MARKETING_VERSION = [^;]*;/MARKETING_VERSION = ${VERSION};/g; s/CURRENT_PROJECT_VERSION = [^;]*;/CURRENT_PROJECT_VERSION = ${BUILD};/g" "$PBX"
grep -q "MARKETING_VERSION = ${VERSION};" "$PBX"

# Icon (single 1024 px universal icon) and launch screen
cp resources/AppIcon-1024.png "$APP/Assets.xcassets/AppIcon.appiconset/AppIcon-512@2x.png"
for f in splash-2732x2732.png splash-2732x2732-1.png splash-2732x2732-2.png; do
  cp resources/splash-2732.png "$APP/Assets.xcassets/Splash.imageset/$f"
done

# Audio session "playback": plays with the silent switch on and keeps going in the background
perl -0pi -e 's/import Capacitor\n/import Capacitor\nimport AVFoundation\n/' "$APP/AppDelegate.swift"
perl -0pi -e 's|(// Override point for customization after application launch\.\n)|$1        // NianPlay: play with the silent switch on and with the screen locked\n        try? AVAudioSession.sharedInstance().setCategory(.playback, mode: .default)\n        try? AVAudioSession.sharedInstance().setActive(true)\n|' "$APP/AppDelegate.swift"
grep -q "import AVFoundation" "$APP/AppDelegate.swift"
grep -q "setCategory(.playback" "$APP/AppDelegate.swift"

echo "--- Info.plist (patched)"
/usr/libexec/PlistBuddy -c "Print" "$PLIST"
echo "--- AppDelegate.swift (head)"
head -20 "$APP/AppDelegate.swift"
